/*
 * MSG-01 · Lista de Hilos — panel de contenido.
 *
 * Nota de paleta: el HTML aprobado usa blanco puro (#fff) para tarjetas, inputs
 * y botones, y ese token no existe en --bw. --bw-surface-mist (#F8F9FB) y
 * --bw-warm-cream (#FAF8F4) son los dos neutros más próximos al blanco; se usan
 * aquí como superficies "blancas".
 */

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.pageTitle {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.pageSub {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 0 1 300px;
  margin: 0;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-surface-mist);
  font-family: inherit;
  font-size: 13px;
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.btnPrimary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.btnPrimary:hover:not(:disabled) {
  opacity: 0.88;
}

.btnPrimary:disabled {
  background: var(--bw-steel-mist);
  color: var(--bw-warm-cream);
  cursor: not-allowed;
}

.scopeNote {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.threadCount {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.errorBox {
  padding: 12px 14px;
  margin-bottom: 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: 13px;
  line-height: 1.5;
}

.statusNote {
  padding: 24px 0;
  margin: 0;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-family: inherit;
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.12s, color 0.12s;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

