import { useEffect, useState } from 'react';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * MSG-02 no existía cuando se escribió esta pantalla y abrir un hilo no lleva
   * a ningún sitio. La prop la cablea App.tsx, así que forma parte de la firma
   * pública de este componente, pero se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Extrae el detalle legible de un fallo. PostgREST no rechaza con `Error`:
 * devuelve un objeto plano `{ code, message }`; pintarlo con `String(e)` o con
 * `e.message` enseña `[object Object]` o `undefined` (F-020).
 */
function errorDetail(e: unknown): string {
  if (e instanceof Error) {
    return e.message || e.name || 'Error desconocido';
  }
  if (e && typeof e === 'object') {
    const err = e as { code?: unknown; message?: unknown };
    const code = typeof err.code === 'string' ? err.code : '';
    const message = typeof err.message === 'string' ? err.message : '';
    const summary = [code, message].filter((part) => part !== '').join(' · ');
    if (summary) return summary;
  }
  const fallback = String(e);
  return fallback === '[object Object]' ? 'Respuesta inesperada del servidor.' : fallback;
}

export function Messages({ profile, now }: MessagesProps) {
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchInput, setSearchInput] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);

  const totalPages = pageCount(total);

  useEffect(() => {
    let ignore = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((data) => {
        if (ignore) return;
        setThreads(data.threads);
        setTotal(data.total);
      })
      .catch((e: unknown) => {
        if (ignore) return;
        setThreads([]);
        setTotal(0);
        setError(errorDetail(e));
      })
      .finally(() => {
        if (!ignore) setLoading(false);
      });

    return () => {
      ignore = true;
    };
  }, [profile.orgId, query, page]);

  return (
    <>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actionsBar}>
        <form
          className={styles.searchForm}
          role="search"
          onSubmit={(e) => {
            e.preventDefault();
            setPage(1);
            setQuery(searchInput.trim());
          }}
        >
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="search"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
          />
        </form>

        {/* DIR-01 no está entre las pantallas del MVP: el control existe, pero no
            lleva a ninguna parte. Se pinta deshabilitado con el motivo visible,
            igual que el botón de subida de INV-01 (F-023 e). */}
        <button type="button" className={styles.btnPrimary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.scopeNote} data-testid="directorio-scope">
          El Directorio (DIR-01) queda fuera del MVP.
        </span>

        <span className={styles.threadCount} data-testid="pag-info">
          {total} hilos · Página {page} de {totalPages}
        </span>
      </div>

      {error && (
        <div role="alert" className={styles.errorBox}>
          No se pudieron cargar los hilos. {error}
        </div>
      )}

      {loading && <p className={styles.statusNote}>Cargando hilos…</p>}

      {!loading && !error && (
        <>
          {/* MSG-02 queda fuera del alcance del MVP: el clic en una fila no navega. */}
          <ThreadList
            threads={threads}
            now={now}
            onOpen={() => {
              /* No-op deliberado: véase onOpenThread en MessagesProps. */
            }}
          />

          {total > 0 && (
            <nav className={styles.pagination} aria-label="Paginación de hilos">
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                aria-label="Página anterior"
                disabled={page <= 1}
                onClick={() => setPage((current) => Math.max(1, current - 1))}
              >
                <i className="ti ti-chevron-left" aria-hidden="true" />
              </button>

              {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
                <button
                  key={n}
                  type="button"
                  className={n === page ? `${styles.pageBtn} ${styles.pageActive}` : styles.pageBtn}
                  aria-current={n === page ? 'page' : undefined}
                  onClick={() => setPage(n)}
                >
                  {n}
                </button>
              ))}

              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                aria-label="Página siguiente"
                disabled={page >= totalPages}
                onClick={() => setPage((current) => Math.min(totalPages, current + 1))}
              >
                <i className="ti ti-chevron-right" aria-hidden="true" />
              </button>
            </nav>
          )}
        </>
      )}
    </>
  );
}

