/*
 * MSG-01 · Lista de Hilos — filas y estado vacío.
 *
 * Nota de paleta: el HTML aprobado usa blanco puro (#fff) para la tarjeta que
 * contiene la lista; ese token no existe en --bw. Se usa --bw-surface-mist
 * (#F8F9FB), el neutro más próximo a blanco puro entre los tokens existentes.
 */

.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  overflow: hidden;
}

.threadItem + .threadItem {
  border-top: 1px solid var(--bw-divider-mist);
}

.threadItem:hover {
  background: var(--bw-row-hover-tint);
}

.rowButton {
  display: grid;
  grid-template-areas:
    'top  meta'
    'bottom  badge';
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: transparent;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -1px;
}

.rowTop {
  grid-area: top;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.timestamp {
  grid-area: meta;
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.rowBottom {
  grid-area: bottom;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.stateBadge {
  grid-area: badge;
  justify-self: end;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

/* Los cuatro primeros badges salen de los tokens de badge del sistema. Para el
   azul de "CON CONSULTA PENDIENTE" no existe par de badge propio: se reutilizan
   los derivados del azul de calibración (--bw-icon-tint-blue y
   --bw-chip-active-border), que son los valores del HTML aprobado. */
.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.toneInfo {
  background: var(--bw-icon-tint-blue);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  text-align: center;
}

.emptyMessage {
  max-width: 48ch;
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-deep-steel);
}

.emptyHint {
  margin: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.emptyButton {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.emptyButton:disabled {
  background: var(--bw-input-placeholder);
  color: var(--bw-warm-cream);
  cursor: not-allowed;
}

