import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * Mapeo tono-a-clase del badge de estado.
 *
 * `Record<StateTone, string | undefined>` a propósito: con
 * `noUncheckedIndexedAccess` cualquier propiedad de `styles` puede faltar, y el
 * `?? ''` del consumo deja la fila sin adorno en vez de escribir "undefined" en
 * el atributo (F-143).
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>
          {
            'Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.'
          }
        </p>
        {/* El botón existe pero DIR-01 queda fuera del MVP: deshabilitado y con
            el motivo visible, igual que el botón de subida de INV-01. */}
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP.</p>
        <button type="button" className={styles.emptyButton} disabled>
          Ir al Directorio
        </button>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => (
        /* El <li> conserva su rol listitem: la pulsación vive en un <button>
           interior, nunca en un role encima del <li> (F-131). */
        <li key={thread.id} className={styles.threadItem}>
          <button
            type="button"
            className={styles.rowButton}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.rowTop}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
              ) : null}
            </span>
            <time className={styles.timestamp} dateTime={thread.lastItemAt}>
              {relativeTime(thread.lastItemAt, now)}
            </time>
            <span className={styles.rowBottom}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
            </span>
            <span className={`${styles.stateBadge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}>
              {thread.state}
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
